/**
 * scripts/dist/build-installer.mjs — bundle the Node plugin installer into one file (HM1-R20).
 *
 * node scripts/dist/build-installer.mjs [--out dist-installer/plur1bus-plugin-installer.mjs]
 *
 * esbuild --bundle --platform=node --format=esm --target=node24.16 over a tiny
 * entry that calls runInstaller(process.argv.slice(2)). `import.meta.filename`
 * is defined away so no bundled module's "run as a script" guard fires inside
 * the bundle (build-plugin-feed.mjs and minisign.mjs have one). Prints the
 * bundle's path and SHA-256 on stdout; exit 0, or 1 with the reason on stderr.
 */

import { createHash } from "node:crypto";
import { mkdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..", "..");
export const DEFAULT_OUT = join(ROOT, "dist-installer", "plur1bus-plugin-installer.mjs");

export async function buildInstaller({ out = DEFAULT_OUT } = {}) {
  const { build } = await import("esbuild");
  const outfile = resolve(out);
  mkdirSync(dirname(outfile), { recursive: true });
  await build({
    stdin: {
      contents: 'import { runInstaller } from "./main.mjs";\nprocess.exitCode = await runInstaller(process.argv.slice(2));\n',
      resolveDir: join(HERE, "installer"),
      sourcefile: "plur1bus-plugin-installer-entry.mjs",
      loader: "js",
    },
    bundle: true,
    platform: "node",
    format: "esm",
    target: "node24.16",
    outfile,
    define: { "import.meta.filename": "undefined" },
    banner: { js: "// PLUR1BUS plugin installer for OpenClaw — generated by scripts/dist/build-installer.mjs; do not edit." },
    legalComments: "none",
    logLevel: "warning",
  });
  const sha256 = createHash("sha256").update(readFileSync(outfile)).digest("hex");
  return { outfile, sha256 };
}

if (import.meta.filename && process.argv[1] === import.meta.filename) {
  try {
    const { values } = parseArgs({ args: process.argv.slice(2), options: { out: { type: "string" } }, strict: true });
    const { outfile, sha256 } = await buildInstaller({ out: values.out });
    process.stdout.write(`${outfile}\nsha256 ${sha256}\n`);
  } catch (err) {
    process.stderr.write(`build-installer: ${err?.message ?? err}\n`);
    process.exitCode = 1;
  }
}
